// Multiple classes in one file for the runnable demo.
package com.bank.cashflow;

import java.util.logging.*;

public class SubarrayDemo {
    private static final Logger log = Logger.getLogger(SubarrayDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Signed daily net cash movements (deposits +, withdrawals -)
        int[] movements = {1, 2, 3, -2, 5};
        int flaggedK = 5;

        SubarrayCounter counter = new SubarrayCounter();
        int count = counter.countSubarrays(movements, flaggedK);

        log.info("Counting date ranges with net movement exactly K=" + flaggedK);
        log.info("Number of matching ranges -> " + count);
    }
}

// ─── Would be in service/SubarrayCounter.java ───
class SubarrayCounter {
    // Prefix sum + HashMap of seen sums. O(n) time, O(n) space. Handles negatives.
    int countSubarrays(int[] nums, int k) {
        java.util.Map<Integer, Integer> seen = new java.util.HashMap<>();
        seen.put(0, 1);  // seed: a prefix equal to K counts (range from start)

        int sum = 0, count = 0;
        for (int x : nums) {
            sum += x;
            // Earlier prefixes equal to (sum - k) each mark a valid subarray end here
            count += seen.getOrDefault(sum - k, 0);
            // Record the current prefix sum occurrence
            seen.merge(sum, 1, Integer::sum);
        }
        return count;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
